test("claim hold scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  await ui.setSetting(pg_uma, "grace-B", "5");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "review-sla", "5");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50", "from": "2026-03-10"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x ", "tags": "c"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "tags": "c"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "50.00", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "50.00"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "20", "termsFrom": "2026-03-12"})).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "B"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00", "tags": " c "}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
