/** Whether the row shows the claim as deferred: it was deferred until a date after the sheet's today, whatever its
 *  status now (a deferred claim later voided still shows it). Only an OPEN one is held back from the totals (`isDeferred`). */
export const deferredShown = (c: { deferredUntil?: string }, today: string | undefined) =>
  !!c.deferredUntil && today !== undefined && today < c.deferredUntil;

export const isDeferred = (c: { status?: string; deferredUntil?: string }, today: string | undefined) =>
  c.status === 'OPEN' && !!c.deferredUntil && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts in the live totals: it counts, is not deferred on the sheet's today, and is not
 *  open, unbound and dated within one of its person's holds (`heldOn`). */
export const countsLive = (c: Claim, heldOn: (date: string) => boolean, today: string | undefined) =>
  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));

/** The status a claim had at the end of the day, as its status log records it (each line dated the sheet's today
 *  when the change was made); undefined when it was added after that day. */
export function statusAt(c: Claim, end: string): ClaimStatus | undefined {
  let at: ClaimStatus | undefined;
  for (const line of c.log ?? []) {
    const m = / on (\d{4}-\d{2}-\d{2}) due=[^ ]*$/.exec(line);
    if (m && m[1] <= end) at = line.slice(0, line.indexOf(' ')) as ClaimStatus;
  }
  return at;
}

/** Whether a claim counts in a period ending on `end`: by the status it had at the end of that day, and, as in the
 *  live totals, not deferred on the sheet's today and not open, unbound and dated within one of its person's holds. */
export const countsAtEnd = (c: Claim, end: string, heldOn: (date: string) => boolean, today: string | undefined) => {
  const then = statusAt(c, end);
  return then !== undefined && counts({ ...c, status: then }) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));
};

export const claimsKey = (sheet: string, asOf = '') => ['sheet', sheet, 'claims', asOf] as const;

 *  remindedOn is the last day a reminder was written for it, "" if never; ref is its external reference, "" for none;
 *  tags are its tags, sorted and comma separated, "" for none; voidReason is the reason it was voided with, "" for none;
 *  comments are its comments, oldest first, each "<user> on <date>: <text>" (empty unless listed);
 *  lines are its lines, oldest first, each "<label> <qty> x <unit>" (empty unless listed);
 *  batch is the number of the bulk settle batch that settled it, "" when settled one at a time or never;
 *  rateMark is the mark drawn when it arrived on the sheet: a forward-only rate applies to it only when its mark is lower;
 *  waived is whether a steward has waived its late charge. */
public record ClaimResponse(String id, String personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String corrects,
        String roundingDate, String dueBy, List<String> log, String deferredUntil, String proofs,
        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref, String tags,
        String voidReason, List<String> comments, String batch, List<String> lines, long rateMark, boolean waived,
        String proofReceipts, String proofPhotos) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(), claim.getNumber() == null ? "" : claim.getNumber(),
                fixedDue(claim) == null ? "" : fixedDue(claim).setScale(2).toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(), claim.isStated(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundingDate().toString(), claim.getDueBy().toString(), claim.getLog(),
                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
                String.valueOf(claim.getProofs()),
                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
                claim.getLockedBy() == null ? "" : claim.getLockedBy(), claim.isLateEntry(),
                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
                claim.getRef() == null ? "" : claim.getRef(),
                claim.getTags() == null ? "" : claim.getTags(),
                claim.getVoidReason() == null ? "" : claim.getVoidReason(),
                claim.getComments().stream().map(ClaimComment::line).toList(),
                claim.getSettleBatch() == null ? "" : String.valueOf(claim.getSettleBatch()),
                claim.getLines().stream().map(ClaimLine::line).toList(), claim.getRateMark(),
                claim.isWaived(), String.valueOf(claim.proofsOf(ProofKind.RECEIPT)),
                String.valueOf(claim.proofsOf(ProofKind.PHOTO)));
    }

    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
    public static java.math.BigDecimal fixedDue(Claim claim) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        return claim.isBound() ? claim.getStatedDue() : null;
    }

    public static List<ClaimResponse> from(List<Claim> claims) {
        return claims.stream().map(ClaimResponse::from).toList();
